using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "AstreaReturnAction", menuName = "Data/Battle/Battle Actions/Enemy/AstreaReturn Action")]
public class SolarRebirthAction : BattleAction
{
	public class AstreaReturnPreviewEffects
	{
		public StartingEffect[] previousEffects;

		public GameObject astreaGameObject;

		public AstreaReturnPreviewEffects(StartingEffect[] previousEffects, GameObject astreaGameObject)
		{
			this.previousEffects = previousEffects;
			this.astreaGameObject = astreaGameObject;
		}
	}

	[Header("Animation")]
	[SerializeField]
	private float delayToSpawnVFXAndPlayAttackAnimation = 0.2f;

	[Header("Solar Rebirth")]
	[SerializeField]
	private OmniSoulEffect omniSoulEffect;

	[SerializeField]
	private CorruptedAnimalData astreaOneCorruptedAnimalData;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("Astrea Level")]
	[SerializeField]
	private DifficultyLevel astreaLevel;

	[NonSerialized]
	private List<AstreaReturnPreviewEffects> astreaReturnPreviewEffectsList = new List<AstreaReturnPreviewEffects>();

	public int GetAstreaOneStartingMaxCorruption()
	{
		int difficultyLevelModifyEnemiesHighestIndex = astreaLevel.GetDifficultyLevelModifyEnemiesHighestIndex();
		int minValue = astreaOneCorruptedAnimalData.GetStartingCorruption(difficultyLevelModifyEnemiesHighestIndex, -1).minValue;
		float difficultyLevelIncreaseMaxCorruptionPercentage = astreaLevel.GetDifficultyLevelIncreaseMaxCorruptionPercentage();
		return minValue + Mathf.CeilToInt((float)minValue * difficultyLevelIncreaseMaxCorruptionPercentage);
	}

	public void SetAstreaOneCorruptedAnimalData(CorruptedAnimalData astreaOneCorruptedAnimalData)
	{
		this.astreaOneCorruptedAnimalData = astreaOneCorruptedAnimalData;
	}

	public override void Cast(GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAstreaBallAction(AstreaReturnCoroutine(source));
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	private IEnumerator AstreaReturnCoroutine(GameObject source)
	{
		yield return new WaitForSeconds(delayToSpawnVFXAndPlayAttackAnimation);
		SpawnVFX(GetVFXOwnerPosition(source), 4f);
		CorruptedAnimalSpriteControl component = source.GetComponent<CorruptedAnimalSpriteControl>();
		component.SetCorruptedAnimalData(astreaOneCorruptedAnimalData);
		component.PlayAnimationForced(AnimationType.Attack, AnimationChangeType.ReturnToIdleAnimation);
		yield return new WaitForSeconds(0.2f);
		UnitEffects component2 = source.GetComponent<UnitEffects>();
		component2.RemoveAllEffectsWithCallbacks();
		component2.AddEffect(omniSoulEffect, EffectsValues.NO_VALUE);
		StartingEffect[] previousEffects = GetAstreaReturnPreviewEffects(source).previousEffects;
		for (int i = 0; i < previousEffects.Length; i++)
		{
			component2.AddEffect(previousEffects[i].Effect, previousEffects[i].EffectAmount);
		}
		CorruptedAnimalCorruptionStats component3 = source.GetComponent<CorruptedAnimalCorruptionStats>();
		component3.SetInfinityCorruption(value: false);
		int astreaOneStartingMaxCorruption = GetAstreaOneStartingMaxCorruption();
		component3.ModifyMaxCorruption(astreaOneStartingMaxCorruption / 2, astreaOneStartingMaxCorruption, 0.5f);
		int difficultyLevelModifyEnemiesHighestIndex = astreaLevel.GetDifficultyLevelModifyEnemiesHighestIndex();
		int maxOverCorruption = astreaOneCorruptedAnimalData.GetMaxOverCorruption(difficultyLevelModifyEnemiesHighestIndex);
		maxOverCorruption += ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.GetCrypticMementoOmenActionAmount();
		component3.ModifyMaxOverCorruptionExactlyNewAmountAndZero(maxOverCorruption);
		CorruptedAnimalInitializer component4 = source.GetComponent<CorruptedAnimalInitializer>();
		component4.CorruptedAnimalOverCorruption.Initialize(astreaOneCorruptedAnimalData);
		component4.InitializeTooltipNameInstance(astreaOneCorruptedAnimalData);
		yield return new WaitForSeconds(0.1f);
	}

	private AstreaReturnPreviewEffects GetAstreaReturnPreviewEffects(GameObject astreaGameObject)
	{
		for (int i = 0; i < astreaReturnPreviewEffectsList.Count; i++)
		{
			if (astreaReturnPreviewEffectsList[i].astreaGameObject == astreaGameObject)
			{
				return astreaReturnPreviewEffectsList[i];
			}
		}
		return null;
	}

	public void PopulateAstreaReturnPreviewEffects(GameObject astreaGameObject, List<EffectInstance> activeEffectsListBeforeRemoval)
	{
		astreaReturnPreviewEffectsList.Remove(GetAstreaReturnPreviewEffects(astreaGameObject));
		bool flag = true;
		for (int i = 0; i < currentCorruptedAnimals.activeCorruptedAnimals.Count; i++)
		{
			GameObject gameObject = currentCorruptedAnimals.activeCorruptedAnimals[i];
			for (int j = 0; j < astreaReturnPreviewEffectsList.Count; j++)
			{
				if (gameObject == astreaReturnPreviewEffectsList[j].astreaGameObject)
				{
					flag = false;
				}
			}
		}
		if (flag)
		{
			astreaReturnPreviewEffectsList.Clear();
		}
		StartingEffect[] array = new StartingEffect[activeEffectsListBeforeRemoval.Count];
		for (int k = 0; k < activeEffectsListBeforeRemoval.Count; k++)
		{
			array[k] = new StartingEffect(activeEffectsListBeforeRemoval[k].Effect, activeEffectsListBeforeRemoval[k].EffectAmount);
		}
		astreaReturnPreviewEffectsList.Add(new AstreaReturnPreviewEffects(array, astreaGameObject));
		GetAstreaReturnPreviewEffects(astreaGameObject);
	}
}
